package com.maramigo.marketplace;

import com.maramigo.accounts.AccountService;
import com.maramigo.catalog.ProductRepository;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
import java.math.*;
import java.time.LocalDate;

/** Deterministic demo payment/commission/refund journal; no provider or real money. @author Maram Abbas */
@RestController @Transactional(readOnly=true)
public class DemoCommerce {
 private final JdbcTemplate db;private final ProductRepository products;
 public DemoCommerce(JdbcTemplate db,ProductRepository products){this.db=db;this.products=products;}
 private long company(long user){var ids=db.queryForList("SELECT company_id FROM merchant_stores WHERE user_id=?",Long.class,user);if(ids.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Store not found.");return ids.get(0);}
 private long money(BigDecimal value){return value.movePointRight(2).longValueExact();}
 private void sale(long order,long company,long gross){String state=db.queryForObject("SELECT status FROM companies WHERE id=? FOR UPDATE",String.class,company);if(!"APPROVED".equals(state))throw fail(HttpStatus.CONFLICT,"This store is not currently accepting orders. Refresh your basket.");long fee=BigDecimal.valueOf(gross).multiply(new BigDecimal("0.05")).setScale(0,RoundingMode.HALF_UP).longValueExact();db.update("INSERT INTO demo_ledger(order_id,company_id,event,gross_agorot,fee_agorot,merchant_agorot,event_key) VALUES (?,?,'SALE',?,?,?,?) ON CONFLICT(event_key) DO NOTHING",order,company,gross,fee,gross-fee,"sale:"+order+":"+company);}
 @Transactional public void capture(long order){
  var rows=db.queryForList("SELECT id,total_price,status FROM orders WHERE id=? FOR UPDATE",order);if(rows.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Order not found.");if(rows.get(0).get("status").equals("CANCELLED"))throw fail(HttpStatus.CONFLICT,"A cancelled order cannot be paid.");
  if(!db.queryForList("SELECT order_id FROM demo_payments WHERE order_id=?",order).isEmpty())return;
  var parts=db.queryForList("SELECT i.company_id,sum(i.unit_price*i.quantity) AS total FROM order_items i JOIN merchant_orders m ON m.order_id=i.order_id AND m.company_id=i.company_id WHERE i.order_id=? AND m.status<>'CANCELLED' GROUP BY i.company_id ORDER BY i.company_id",order);
  long amount=parts.stream().mapToLong(p->money((BigDecimal)p.get("total"))).sum();if(amount<=0)throw fail(HttpStatus.CONFLICT,"A cancelled order cannot be paid.");
  db.update("INSERT INTO demo_payments(order_id,status,amount_agorot) VALUES (?,'CAPTURED',?)",order,amount);
  for(var part:parts){long c=((Number)part.get("company_id")).longValue();sale(order,c,money((BigDecimal)part.get("total")));}
 }
 @GetMapping("/api/customer/payments") public List<Map<String,Object>> customerPayments(@AuthenticationPrincipal AccountService.Principal user,@RequestParam(defaultValue="0") @Min(0) int page){return db.queryForList("SELECT o.order_number,p.status,p.amount_agorot,p.refunded_agorot,p.created_at FROM demo_payments p JOIN orders o ON o.id=p.order_id WHERE o.user_id=? ORDER BY o.id DESC LIMIT 20 OFFSET ?",user.id(),(long)page*20);}
 @GetMapping("/api/customer/payments/{number}") public Map<String,Object> payment(@PathVariable String number,@AuthenticationPrincipal AccountService.Principal user){var ids=db.queryForList("SELECT id FROM orders WHERE order_number=? AND user_id=?",Long.class,number,user.id());if(ids.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Order not found.");var rows=db.queryForList("SELECT status,amount_agorot,refunded_agorot,created_at FROM demo_payments WHERE order_id=?",ids.get(0));return rows.isEmpty()?Map.of("status","UNPAID","simulated",true):withDemo(rows.get(0));}
 @PostMapping("/api/customer/payments/{number}") @Transactional public void pay(@PathVariable String number,@AuthenticationPrincipal AccountService.Principal user){var ids=db.queryForList("SELECT id FROM orders WHERE order_number=? AND user_id=?",Long.class,number,user.id());if(ids.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Order not found.");capture(ids.get(0));}
 private Map<String,Object> withDemo(Map<String,Object> value){var result=new LinkedHashMap<>(value);result.put("simulated",true);return result;}
 @GetMapping("/api/merchant/finance") public Map<String,Object> merchantFinance(@AuthenticationPrincipal AccountService.Principal user,@RequestParam(defaultValue="0") @Min(0) int page){return finance(company(user.id()),page);}
 @GetMapping("/api/admin/finance") public Map<String,Object> platformFinance(@RequestParam(defaultValue="0") @Min(0) int page){return finance(null,page);}
 private Map<String,Object> finance(Long company,int page){String where=company==null?"":" WHERE company_id="+company;var result=new LinkedHashMap<String,Object>();result.put("simulated",true);result.put("totals",db.queryForMap("SELECT coalesce(sum(gross_agorot),0) AS gross_agorot,coalesce(sum(fee_agorot),0) AS platform_agorot,coalesce(sum(merchant_agorot),0) AS merchant_agorot FROM demo_ledger"+where));result.put("payoutAgorot",db.queryForObject("SELECT coalesce(sum(amount_agorot),0) FROM demo_payouts"+where,Long.class));result.put("entries",db.queryForList("SELECT l.id,l.event,l.gross_agorot,l.fee_agorot,l.merchant_agorot,l.created_at,c.name AS company_name,o.order_number FROM demo_ledger l JOIN companies c ON c.id=l.company_id LEFT JOIN orders o ON o.id=l.order_id"+(company==null?"":" WHERE l.company_id="+company)+" ORDER BY l.id DESC LIMIT 20 OFFSET ?",(long)page*20));if(company!=null)result.put("subscription",db.queryForList("SELECT CASE WHEN status='ACTIVE' AND period_end<(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Jerusalem')::date THEN 'EXPIRED' ELSE status END AS status,period_start,period_end,consent_at FROM demo_subscriptions WHERE company_id=?",company));return result;}
 public record Subscribe(@AssertTrue boolean consent){}
 @PostMapping("/api/merchant/subscription") @Transactional public void subscribe(@AuthenticationPrincipal AccountService.Principal user,@Valid @RequestBody Subscribe form){long c=company(user.id());db.queryForObject("SELECT id FROM companies WHERE id=? FOR UPDATE",Long.class,c);if(!"APPROVED".equals(db.queryForObject("SELECT status FROM companies WHERE id=?",String.class,c)))throw fail(HttpStatus.CONFLICT,"Only approved stores can activate a demo subscription.");var existing=db.queryForList("SELECT status,period_end FROM demo_subscriptions WHERE company_id=?",c);if(!existing.isEmpty()&&!((java.sql.Date)existing.get(0).get("period_end")).toLocalDate().isBefore(LocalDate.now(java.time.ZoneId.of("Asia/Jerusalem")))){db.update("UPDATE demo_subscriptions SET status='ACTIVE',cancelled_at=NULL WHERE company_id=?",c);return;}LocalDate start=LocalDate.now(java.time.ZoneId.of("Asia/Jerusalem")),end=start.plusMonths(1);db.update("INSERT INTO demo_subscriptions(company_id,status,consent_at,period_start,period_end) VALUES (?,'ACTIVE',CURRENT_TIMESTAMP,?,?) ON CONFLICT(company_id) DO UPDATE SET status='ACTIVE',consent_at=CURRENT_TIMESTAMP,period_start=excluded.period_start,period_end=excluded.period_end,cancelled_at=NULL",c,start,end);db.update("INSERT INTO demo_ledger(company_id,event,gross_agorot,fee_agorot,merchant_agorot,event_key) VALUES (?,'SUBSCRIPTION',9900,9900,0,?) ON CONFLICT(event_key) DO NOTHING",c,"subscription:"+c+":"+start);}
 @DeleteMapping("/api/merchant/subscription") @Transactional public void unsubscribe(@AuthenticationPrincipal AccountService.Principal user){long c=company(user.id());db.update("UPDATE demo_subscriptions SET status='CANCELLED',cancelled_at=CURRENT_TIMESTAMP WHERE company_id=?",c);}
 public record Return(@Positive long companyId,@NotBlank @Pattern(regexp="CANCEL|RETURN") String kind,@NotBlank @Size(max=1000) String reason){}
 public record Decision(@NotBlank @Pattern(regexp="COMPLETED|REJECTED") String status,@NotBlank @Size(max=1000) String reason){}
 @PostMapping("/api/customer/returns/{number}") @Transactional public void request(@PathVariable String number,@Valid @RequestBody Return form,@AuthenticationPrincipal AccountService.Principal user){
  var ids=db.queryForList("SELECT id FROM orders WHERE order_number=? AND user_id=? FOR UPDATE",Long.class,number,user.id());if(ids.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Order not found.");long order=ids.get(0);var states=db.queryForList("SELECT status FROM merchant_orders WHERE order_id=? AND company_id=? FOR UPDATE",String.class,order,form.companyId());if(states.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Store part not found.");
  if(!db.queryForList("SELECT id FROM return_requests WHERE order_id=? AND company_id=? AND status IN ('PENDING','COMPLETED')",order,form.companyId()).isEmpty())return;
  if(!(form.kind().equals("CANCEL")&&states.get(0).equals("PENDING")||form.kind().equals("RETURN")&&states.get(0).equals("DELIVERED")))throw fail(HttpStatus.CONFLICT,"Cancellation is available before shipping; returns are available after delivery.");
  Long id=db.queryForObject("INSERT INTO return_requests(order_id,company_id,customer_id,kind,reason) VALUES (?,?,?,?,?) RETURNING id",Long.class,order,form.companyId(),user.id(),form.kind(),form.reason().trim());if(form.kind().equals("CANCEL"))complete(order,form.companyId(),id,user.id(),"Cancelled by customer before shipping.");
 }
 @GetMapping("/api/customer/returns/{number}") public List<Map<String,Object>> customerReturns(@PathVariable String number,@AuthenticationPrincipal AccountService.Principal user){return db.queryForList("SELECT r.id,r.company_id,c.name AS company_name,r.kind,r.status,r.reason,r.resolution,r.created_at FROM return_requests r JOIN orders o ON o.id=r.order_id JOIN companies c ON c.id=r.company_id WHERE o.order_number=? AND o.user_id=? ORDER BY r.id DESC",number,user.id());}
 @GetMapping("/api/merchant/returns") public List<Map<String,Object>> merchantReturns(@AuthenticationPrincipal AccountService.Principal user,@RequestParam(defaultValue="0") @Min(0) int page){return returns(company(user.id()),page);}
 @GetMapping("/api/admin/returns") public List<Map<String,Object>> adminReturns(@RequestParam(defaultValue="0") @Min(0) int page){return returns(null,page);}
 private List<Map<String,Object>> returns(Long c,int page){return db.queryForList("SELECT r.id,o.order_number,c.name AS company_name,r.kind,r.status,r.reason,r.resolution,r.created_at FROM return_requests r JOIN orders o ON o.id=r.order_id JOIN companies c ON c.id=r.company_id"+(c==null?"":" WHERE r.company_id="+c)+" ORDER BY r.id DESC LIMIT 20 OFFSET ?",(long)page*20);}
 @PostMapping({"/api/merchant/returns/{id}","/api/admin/returns/{id}"}) @Transactional public void decide(@PathVariable long id,@Valid @RequestBody Decision form,@AuthenticationPrincipal AccountService.Principal user){var rows=db.queryForList("SELECT order_id,company_id FROM return_requests WHERE id=?",id);if(rows.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Request not found.");long c=((Number)rows.get(0).get("company_id")).longValue(),order=((Number)rows.get(0).get("order_id")).longValue();if(!user.role().equals("ADMIN")&&c!=company(user.id()))throw fail(HttpStatus.NOT_FOUND,"Request not found.");db.queryForObject("SELECT id FROM orders WHERE id=? FOR UPDATE",Long.class,order);var state=db.queryForObject("SELECT status FROM return_requests WHERE id=? FOR UPDATE",String.class,id);if(!"PENDING".equals(state))return;if(form.status().equals("COMPLETED"))complete(order,c,id,user.id(),form.reason());else db.update("UPDATE return_requests SET status='REJECTED',resolution=?,actor_id=?,resolved_at=CURRENT_TIMESTAMP WHERE id=?",form.reason().trim(),user.id(),id);}
 private void complete(long order,long c,long request,long actor,String reason){
  String before=db.queryForObject("SELECT status FROM merchant_orders WHERE order_id=? AND company_id=? FOR UPDATE",String.class,order,c);if("CANCELLED".equals(before))throw fail(HttpStatus.CONFLICT,"This order part was already cancelled.");
  var items=db.queryForList("SELECT product_id,quantity FROM order_items WHERE order_id=? AND company_id=? ORDER BY product_id",order,c);for(var item:items){long p=((Number)item.get("product_id")).longValue();int quantity=((Number)item.get("quantity")).intValue();var product=products.findLockedById(p).orElseThrow();if((long)product.getStockQuantity()+quantity>1000000)throw fail(HttpStatus.CONFLICT,"Restoring stock would exceed the inventory limit.");product.adjustStock(quantity);db.update("INSERT INTO inventory_movements(product_id,actor_id,quantity_delta,reason,order_id) VALUES (?,?,?,?,?)",p,actor,quantity,"Return/cancellation #"+request,order);}products.flush();
  db.update("UPDATE merchant_orders SET status='CANCELLED',version=version+1 WHERE order_id=? AND company_id=?",order,c);db.update("INSERT INTO merchant_order_history(order_id,company_id,actor_id,from_status,to_status,reason) VALUES (?,?,?,?,'CANCELLED',?)",order,c,actor,before,reason);
  refundPart(order,c);
  db.update("UPDATE return_requests SET status='COMPLETED',resolution=?,actor_id=?,resolved_at=CURRENT_TIMESTAMP WHERE id=?",reason.trim(),actor,request);
  aggregate(order,actor,reason);
 }
 @Transactional public void refundPart(long order,long c){db.queryForObject("SELECT id FROM companies WHERE id=? FOR UPDATE",Long.class,c);var sales=db.queryForList("SELECT gross_agorot,fee_agorot,merchant_agorot FROM demo_ledger WHERE event_key=?","sale:"+order+":"+c);if(sales.isEmpty())return;var sale=sales.get(0);long gross=((Number)sale.get("gross_agorot")).longValue();if(db.update("INSERT INTO demo_ledger(order_id,company_id,event,gross_agorot,fee_agorot,merchant_agorot,event_key) VALUES (?,?,'REFUND',?,?,?,?) ON CONFLICT DO NOTHING",order,c,-gross,-((Number)sale.get("fee_agorot")).longValue(),-((Number)sale.get("merchant_agorot")).longValue(),"refund:"+order+":"+c)==0)return;db.update("UPDATE demo_payments SET refunded_agorot=refunded_agorot+?,status=CASE WHEN refunded_agorot+?=amount_agorot THEN 'REFUNDED' ELSE 'PARTIAL_REFUND' END WHERE order_id=?",gross,gross,order);}
 private void aggregate(long order,long actor,String reason){var states=db.queryForList("SELECT status FROM merchant_orders WHERE order_id=?",String.class,order);var active=states.stream().filter(s->!s.equals("CANCELLED")).toList();String status=active.isEmpty()?"CANCELLED":active.stream().allMatch("DELIVERED"::equals)?"DELIVERED":active.stream().anyMatch(s->s.equals("SHIPPED")||s.equals("DELIVERED"))?"SHIPPED":"PENDING";String before=db.queryForObject("SELECT status FROM orders WHERE id=?",String.class,order);db.update("UPDATE orders SET status=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",status,order);if(!status.equals(before))db.update("INSERT INTO order_status_history(order_id,actor_id,from_status,to_status,reason) VALUES (?,?,?,?,?)",order,actor,before,status,reason);}

 public record Payout(@NotNull UUID requestKey){}
 @GetMapping("/api/admin/payouts") public List<Map<String,Object>> payouts(){return db.queryForList("SELECT c.id,c.name,coalesce((SELECT sum(l.merchant_agorot) FROM demo_ledger l WHERE l.company_id=c.id),0)-coalesce((SELECT sum(p.amount_agorot) FROM demo_payouts p WHERE p.company_id=c.id),0) AS available_agorot FROM companies c WHERE EXISTS(SELECT 1 FROM demo_ledger l WHERE l.company_id=c.id) ORDER BY c.id");}
 @PostMapping("/api/admin/payouts/{company}") @Transactional public void payout(@PathVariable long company,@Valid @RequestBody Payout form,@AuthenticationPrincipal AccountService.Principal owner){if(!db.queryForList("SELECT id FROM demo_payouts WHERE request_key=?",form.requestKey()).isEmpty())return;if(db.queryForList("SELECT id FROM companies WHERE id=? FOR UPDATE",company).isEmpty())throw fail(HttpStatus.NOT_FOUND,"Store not found.");if(!db.queryForList("SELECT id FROM demo_payouts WHERE request_key=?",form.requestKey()).isEmpty())return;long balance=db.queryForObject("SELECT coalesce((SELECT sum(merchant_agorot) FROM demo_ledger WHERE company_id=?),0)-coalesce((SELECT sum(amount_agorot) FROM demo_payouts WHERE company_id=?),0)",Long.class,company,company);if(balance<=0)throw fail(HttpStatus.CONFLICT,"No positive demo balance is available.");db.update("INSERT INTO demo_payouts(company_id,actor_id,amount_agorot,request_key) VALUES (?,?,?,?)",company,owner.id(),balance,form.requestKey());}
 private static ResponseStatusException fail(HttpStatus status,String text){return new ResponseStatusException(status,text);}
}
